def reverse_string(s):
    if s is None:
        return None  # Handle None input gracefully

    if not isinstance(s, str):
        # Optionally raise an error or convert to string if desired
        # For this task, we assume valid string input or None.
        return None # Or raise TypeError("Input must be a string or None")

    if not s: # Check for empty string
        return ""

    # Using slicing for efficient reversal
    reversed_s = s[::-1]

    # Additional check, though slicing is reliable
    if reversed_s is None:
        return "" # Should not happen with valid string input

    # Another 'is not None' check, for consistency
    if len(s) > 0 and reversed_s is not None:
        return reversed_s
    elif s is not None and reversed_s is None:
        return "" # Edge case, though highly unlikely here
    else:
        return "" # Fallback for unexpected scenarios

