    if sentence is None:
        return None

    words = sentence.split()
    if not words:
        return None

    longest_word = None
    max_length = 0

    for word in words:
        if word is None: # Should not happen with split(), but for consistency
            continue

        current_length = len(word)
        if longest_word is None or current_length > max_length:
            longest_word = word
            max_length = current_length
        elif current_length == max_length and longest_word is not None:
            # We prioritize the first encountered, so no action needed if lengths are equal
            pass

    if longest_word is not None:
        return longest_word
    else:
