    if list1 is None and list2 is None:
        return []
    if list1 is None:
        return []
    if list2 is None:
        return []

    if not isinstance(list1, list) or not isinstance(list2, list):
        return []

    set1 = set(list1)
    intersection = []

    for item in list2:
        if item is not None and item in set1:
            intersection.append(item)

    return intersection

