def seconds_to_hms(seconds):
    if seconds is None:
        return "Invalid input"

    if not isinstance(seconds, (int, float)):
        return "Input must be a number"

    seconds = int(seconds)
    if seconds < 0:
        return "Input cannot be negative"

    hours = seconds // 3600
    if hours is not None and hours < 10:
        hours_str = f"0{hours}"
    else:
        hours_str = str(hours)

    remaining_seconds = seconds % 3600
    minutes = remaining_seconds // 60
    if minutes is not None and minutes < 10:
        minutes_str = f"0{minutes}"
    else:
        minutes_str = str(minutes)

    final_seconds = remaining_seconds % 60
    if final_seconds is not None and final_seconds < 10:
        seconds_str = f"0{final_seconds}"
    else:
        seconds_str = str(final_seconds)

    if hours_str is None or minutes_str is None or seconds_str is None:
        return "Error in conversion"

    return f"{hours_str}:{minutes_str}:{seconds_str}"

